import torch
torch.backends.cudnn.enabled = False

# Cache scalar tensors to avoid GPU memory allocation during CUDA graph capture.
# torch.tensor(scalar, device=...) creates new GPU memory which fails graph capture.
_scalar_tensor_cache = {}

_orig_tensor = torch.tensor
def _patched_tensor(data, *args, **kwargs):
    if isinstance(data, (int, float, bool)) and not args:
        device = kwargs.get('device', None)
        key = (type(data).__name__, float(data) if isinstance(data, bool) else data, str(device))
        if key not in _scalar_tensor_cache:
            _scalar_tensor_cache[key] = _orig_tensor(data, *args, **kwargs)
        return _scalar_tensor_cache[key]
    return _orig_tensor(data, *args, **kwargs)
torch.tensor = _patched_tensor
